import { chromium } from 'playwright';
import { readFileSync } from 'fs';
import { resolve } from 'path';

const htmlPath = resolve('/app/output/poster.html');
const outputPath = resolve('/app/output/final_poster.png');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();

// Set viewport to poster width
await page.setViewportSize({ width: 1080, height: 600 });

// Load the HTML file
await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

// Wait for fonts to load
await page.waitForTimeout(2000);

// Get the actual height of the poster content
const height = await page.evaluate(() => {
  return document.querySelector('.poster').scrollHeight;
});

// Resize viewport to fit the full poster
await page.setViewportSize({ width: 1080, height: height + 20 });

// Take the screenshot
await page.screenshot({
  path: outputPath,
  fullPage: false,
  type: 'png',
});

console.log(`Poster saved to ${outputPath}`);
console.log(`Dimensions: 1080 x ${height + 20}`);

await browser.close();

